import { loadFont as loadCinzel } from "@remotion/google-fonts/Cinzel";
import { loadFont as loadGaramond } from "@remotion/google-fonts/EBGaramond";
import React from "react";
import { AbsoluteFill, Easing, Img, OffthreadVideo, Sequence, interpolate, staticFile, useCurrentFrame } from "remotion";
import { Cena, Desenho } from "./Desenhos";
import { EMB1_DUR, EMB1_FRASES, EMB2_DUR, EMB2_FRASES, EMB3_DUR, EMB3_FRASES, EMB4_DUR, EMB4_FRASES } from "./embDadosV2";

// v2 (28/10): o dono pediu "mais motions, intercalar entre imagens e motions" e "garanta que vai falar o nome da marca certo JRE".
// Vozes regravadas com "Jota-Érre-É" (a transcrição ouve JRE nas 8 menções) e cenas desenhadas (Desenhos.tsx, no estilo do
// vídeo do R) alternando com as imagens mais ou menos a cada frase; cada vídeo abre com um desenho diferente. Na tela, "JRE".
// v1 continua em Embaixador.tsx.
// JRE · Programa Embaixador (28/10): três vídeos com o roteiro do cliente. 1 = apresentação (Conheça o convite),
// 2 = como funciona a Lista VIP, 3 = o caminho da Lista VIP ao Embaixador.
// Muito material (14 artes + o vídeo da revista folheada) → vitrine: a imagem ocupa o quadro inteiro, lettering na parte de
// baixo, logo pequeno em cima, movimento suave na imagem e troca de imagem a cada frase.
// Identidade da série: preto e dourado, Cinzel em caixa alta + EB Garamond. As artes vieram com a marca "Dola AI" no canto:
// cortadas no preparo (public/jre/emb/f*.jpg); o texto sem sentido do cartão (foto 2) está desfocado; "EXCLUSIVE
// PRIVILEGES" da foto 7 ficou fora do corte.
// Cada vídeo abre com um recurso diferente (capa da revista, porta abrindo, caminho de luz) e tem o seu jogo de transições.
// Tempos = tempos da voz cortada (public/jre/emb/voz<N>.wav); o vídeo tem LEAD.

const { fontFamily: CAPS } = loadCinzel("normal", { weights: ["500", "600"], subsets: ["latin", "latin-ext"] });
const { fontFamily: SERIF } = loadGaramond("normal", { weights: ["500", "600"], subsets: ["latin", "latin-ext"] });
const { fontFamily: SERIF_I } = loadGaramond("italic", { weights: ["500", "600"], subsets: ["latin", "latin-ext"] });

export const EMB2_FPS = 30;
const EMB_FPS = EMB2_FPS;
const LEAD = 0.35;
const END = 3.4;
const cl = { extrapolateLeft: "clamp", extrapolateRight: "clamp" } as const;
const OUT = Easing.bezier(0.16, 1, 0.3, 1);
const INOUT = Easing.bezier(0.65, 0, 0.35, 1);
const k = (t: number, a: number, d = 0.5) => interpolate(t, [a, a + d], [0, 1], { ...cl, easing: OUT });
const io = (t: number, a: number, b: number) => interpolate(t, [a, b], [0, 1], { ...cl, easing: INOUT });
const lin = (t: number, a: number, b: number) => interpolate(t, [a, b], [0, 1], cl);

const CREAM = "#F2E6CC";
const GOLD = "#D6B169";
const GOLD_GRAD = "linear-gradient(100deg,#8E6A2F 0%,#C9A25A 22%,#F6E2B0 40%,#FFF4D6 46%,#E2C17D 56%,#B08A45 78%,#8E6A2F 100%)";
const gold = (t: number, speed = 0.16, off = 0): React.CSSProperties => ({
  backgroundImage: GOLD_GRAD, backgroundSize: "260% 100%", backgroundPosition: `${(100 - ((t * speed * 100 + off) % 200)).toFixed(1)}% 50%`,
  WebkitBackgroundClip: "text", backgroundClip: "text", color: "transparent",
});
const blurIn = (t: number, at: number, out?: number, d = 0.45): React.CSSProperties => {
  const e = k(t, at, d);
  const o = out === undefined ? 0 : lin(t, out, out + 0.18);
  return { opacity: Math.min(1, e * 1.5) * (1 - o), filter: `blur(${((1 - e) * 14 + o * 12).toFixed(1)}px)`, transform: `scale(${(1.16 - 0.16 * e).toFixed(4)})` };
};

type Move = "in" | "out" | "left" | "right" | "up";
type Trans = "flash" | "zoom" | "blur" | "doors" | "wipe" | "iris" | "push" | "diag" | "slide" | "page" | "curtain" | "light";
// src: foto (f<N>) ou trecho da revista (segundo de início no vídeo da revista)
// rate: velocidade do trecho da revista (só no vídeo 4); com rate, o trecho está no segundo src exatamente no início da cena
type Shot = { at: number; src: string | number; move: Move; tr?: Trans; rate?: number };
type Cfg = { dur: number; frases: [[string, number][], number][]; shots: Shot[]; kicker: string; cta: [string, string] };

// ───────── imagem com movimento suave ─────────
const Media: React.FC<{ s: Shot; t: number; next: number }> = ({ s, t, next }) => {
  const p = lin(t, s.at - 0.4, next + 0.4);
  const m = s.move;
  const sc = m === "in" ? 1.03 + 0.09 * p : m === "out" ? 1.12 - 0.09 * p : 1.1;
  const tx = m === "left" ? 40 - 80 * p : m === "right" ? -40 + 80 * p : 0;
  const ty = m === "up" ? 40 - 80 * p : 0;
  const style: React.CSSProperties = { width: "100%", height: "100%", objectFit: "cover", transform: `translate(${tx.toFixed(1)}px, ${ty.toFixed(1)}px) scale(${sc.toFixed(4)})` };
  if (typeof s.src === "string" && s.src.startsWith("m:")) return <Cena kind={s.src.slice(2) as Desenho} u={t - s.at} d={next - s.at} />;
  if (typeof s.src === "number") {
    const from = Math.round((s.at - 0.6 + LEAD) * EMB_FPS);
    return (
      <Sequence from={Math.max(0, from)} layout="none">
        <OffthreadVideo src={staticFile("jre/emb/revista.mp4")} muted startFrom={s.rate ? Math.round((s.src - 0.6 * s.rate) * EMB_FPS) : Math.round(s.src * EMB_FPS) + Math.max(0, -from)} playbackRate={s.rate ?? 1} style={{ ...style, filter: "contrast(1.06) saturate(1.05)" }} />
      </Sequence>
    );
  }
  return <Img src={staticFile(`jre/emb/${s.src}.jpg`)} style={style} />;
};

// entrada da imagem nova por cima da anterior (p 0→1)
const enterStyle = (tr: Trans, p: number): React.CSSProperties => {
  const q = 1 - p;
  switch (tr) {
    case "flash": return { opacity: p };
    case "zoom": return { opacity: Math.min(1, p * 1.6), transform: `scale(${(1 + 0.35 * q).toFixed(4)})` };
    case "blur": return { opacity: p, filter: `blur(${(q * 24).toFixed(1)}px)` };
    case "doors": return { clipPath: `inset(0 ${(q * 50).toFixed(2)}% 0 ${(q * 50).toFixed(2)}%)` };
    case "wipe": return { WebkitMaskImage: `linear-gradient(90deg, black ${(p * 130 - 30).toFixed(1)}%, transparent ${(p * 130).toFixed(1)}%)` };
    case "iris": return { clipPath: `circle(${(p * 120).toFixed(2)}% at 50% 45%)` };
    case "push": return { transform: `translateY(${(q * 1920).toFixed(1)}px)` };
    case "diag": return { WebkitMaskImage: `linear-gradient(125deg, black ${(p * 140 - 40).toFixed(1)}%, transparent ${(p * 140).toFixed(1)}%)` };
    case "slide": return { transform: `translateX(${(q * 1080).toFixed(1)}px)` };
    case "page": return { transform: `perspective(2400px) rotateY(${(-70 * q).toFixed(2)}deg)`, transformOrigin: "0px 960px", opacity: Math.min(1, p * 2.5) };
    case "curtain": return { WebkitMaskImage: `linear-gradient(180deg, black ${(p * 130 - 30).toFixed(1)}%, transparent ${(p * 130).toFixed(1)}%)` };
    case "light": return { opacity: p, filter: `brightness(${(1 + 1.6 * q).toFixed(3)})` };
  }
};
const exitStyle = (tr: Trans, p: number): React.CSSProperties =>
  tr === "zoom" ? { transform: `scale(${(1 + 0.25 * p).toFixed(4)})`, opacity: 1 - 0.5 * p }
  : tr === "push" ? { transform: `translateY(${(-p * 700).toFixed(1)}px)` }
  : tr === "page" ? { transform: `perspective(2400px) rotateY(${(25 * p).toFixed(2)}deg)`, transformOrigin: "1080px 960px", filter: `brightness(${(1 - 0.5 * p).toFixed(3)})` }
  : tr === "light" ? { filter: `brightness(${(1 + 1.6 * p).toFixed(3)})` }
  : tr === "slide" ? { transform: `translateX(${(-p * 500).toFixed(1)}px)`, opacity: 1 - 0.4 * p }
  : {};
const TD = 0.42;

// ───────── lettering embaixo ─────────
const Lettering: React.FC<{ t: number; frases: Cfg["frases"]; stop: number; hide: (a: number) => boolean }> = ({ t, frases, stop, hide }) => (
  <>
    {frases.map(([lines, end], i) => {
      const nextAt = i + 1 < frases.length ? frases[i + 1][0][0][1] : stop;
      const out = Math.min(nextAt - 0.2, Math.max(end + 0.35, nextAt - 0.2));
      if (t < lines[0][1] - 0.3 || t > out + 0.4 || hide(lines[0][1])) return null;
      const longest = Math.max(...lines.map(([l]) => l.replace(/\*/g, "").length));
      const size = Math.min(78, Math.round(840 / (longest * 0.45)));
      return (
        <div key={i} style={{ position: "absolute", left: 120, right: 120, top: 1390, display: "flex", flexDirection: "column", alignItems: "center", gap: 4 }}>
          {lines.map(([l, at], j) => (
            <div key={j} style={{ fontFamily: SERIF, fontWeight: 500, fontSize: size, lineHeight: 1.14, color: CREAM, whiteSpace: "nowrap", textAlign: "center", textShadow: "0 2px 18px rgba(0,0,0,0.65)", ...blurIn(t, at - 0.05, out) }}>
              {l.split(/(\*[^*]+\*)/).filter(Boolean).map((seg, x) =>
                seg.startsWith("*") ? <span key={x} style={{ fontFamily: SERIF_I, fontWeight: 600, ...gold(t, 0.16, x * 30), textShadow: "none", filter: "drop-shadow(0 2px 10px rgba(0,0,0,0.6))" }}>{seg.slice(1, -1)}</span> : <span key={x}>{seg}</span>,
              )}
            </div>
          ))}
        </div>
      );
    })}
  </>
);

// ───────── cartão final ─────────
const Final: React.FC<{ t: number; at: number; cta: [string, string] }> = ({ t, at, cta }) => {
  const e = k(t, at, 0.9);
  const W = 560, H = (W * 686) / 712;
  const sweep = lin(t, at + 0.6, at + 1.6);
  return (
    <AbsoluteFill style={{ opacity: lin(t, at - 0.15, at + 0.3), background: "radial-gradient(circle at 50% 42%, #2A2012 0%, #0A0806 60%)" }}>
      <div style={{ position: "absolute", left: 540 - W / 2, top: 430, width: W, height: H, opacity: e, filter: `blur(${((1 - e) * 18).toFixed(1)}px)`, transform: `scale(${(1.25 - 0.25 * e + 0.04 * lin(t, at, at + END)).toFixed(4)})` }}>
        <Img src={staticFile("jre/logo.png")} style={{ width: W, height: H }} />
        <div style={{ position: "absolute", inset: 0, WebkitMaskImage: `url(${staticFile("jre/logo.png")})`, WebkitMaskSize: "100% 100%",
          background: `linear-gradient(105deg, transparent ${(sweep * 160 - 40).toFixed(1)}%, rgba(255,246,220,0.85) ${(sweep * 160 - 25).toFixed(1)}%, transparent ${(sweep * 160 - 10).toFixed(1)}%)`, mixBlendMode: "screen" }} />
      </div>
      <div style={{ position: "absolute", left: 120, right: 120, top: 1050, textAlign: "center", fontFamily: CAPS, fontWeight: 500, fontSize: 52, letterSpacing: "0.22em", marginRight: "-0.22em", ...gold(t, 0.2), ...blurIn(t, at + 0.5) }}>DO PEÃO AO REI</div>
      <div style={{ position: "absolute", left: 540 - 230 * k(t, at + 0.8, 0.8), width: 460 * k(t, at + 0.8, 0.8), top: 1142, height: 2, background: `linear-gradient(90deg, transparent, ${GOLD}, transparent)` }} />
      <div style={{ position: "absolute", left: 0, right: 0, top: 1250, display: "flex", justifyContent: "center", ...blurIn(t, at + 0.9) }}>
        <div style={{ padding: "26px 64px", borderRadius: 999, border: `2px solid ${GOLD}`, background: "linear-gradient(180deg, rgba(214,177,105,0.22), rgba(214,177,105,0.06))", fontFamily: CAPS, fontWeight: 600, fontSize: 44, letterSpacing: "0.12em", ...gold(t, 0.3), boxShadow: `0 0 ${(30 + 14 * Math.sin(t * 3)).toFixed(0)}px rgba(214,177,105,0.35)` }}>{cta[0]}</div>
      </div>
      <div style={{ position: "absolute", left: 120, right: 120, top: 1420, textAlign: "center", fontFamily: SERIF_I, fontWeight: 500, fontSize: 50, color: CREAM, ...blurIn(t, at + 1.2) }}>{cta[1]}</div>
    </AbsoluteFill>
  );
};

const Video: React.FC<{ c: Cfg }> = ({ c }) => {
  const frame = useCurrentFrame();
  const t = frame / EMB_FPS - LEAD;
  const endAt = c.dur + 0.25;
  const S = c.shots;
  const kickE = k(t, -0.2, 0.6), kickO = lin(t, 2.0, 2.3);
  return (
    <AbsoluteFill style={{ background: "#0A0806", overflow: "hidden" }}>
      {S.map((s, i) => {
        const next = i + 1 < S.length ? S[i + 1].at : endAt;
        if (t < s.at - TD - 0.05 || t > next + 0.05) return null;
        const pin = s.tr && i > 0 ? io(t, s.at - TD, s.at) : 1;
        const nt = i + 1 < S.length ? S[i + 1].tr : undefined;
        const pout = nt ? io(t, next - TD, next) : 0;
        return (
          <AbsoluteFill key={i} style={{ ...(pin < 1 && s.tr ? enterStyle(s.tr, pin) : {}) }}>
            <AbsoluteFill style={pout > 0 && nt ? exitStyle(nt, pout) : {}}>
              <Media s={s} t={t} next={next} />
            </AbsoluteFill>
          </AbsoluteFill>
        );
      })}
      {/* clarão dourado nas trocas "flash" */}
      {S.map((s, i) => s.tr === "flash" && i > 0 ? (
        <AbsoluteFill key={`f${i}`} style={{ background: "radial-gradient(circle at 50% 45%, rgba(255,226,160,0.9), rgba(214,160,80,0.25) 55%, transparent 80%)", opacity: Math.max(0, 1 - Math.abs(t - (s.at - TD / 2)) / (TD / 2)) * 0.55, mixBlendMode: "screen" }} />
      ) : null)}
      {/* véu escuro em cima (logo) e embaixo (lettering) */}
      <AbsoluteFill style={{ background: "linear-gradient(180deg, rgba(0,0,0,0.55) 0%, rgba(0,0,0,0) 18%, rgba(0,0,0,0) 52%, rgba(0,0,0,0.78) 74%, rgba(0,0,0,0.9) 100%)" }} />
      <div style={{ position: "absolute", left: 540 - 72, top: 92, width: 144, height: 139, opacity: k(t, 2.2, 0.8) * (1 - lin(t, endAt - 0.3, endAt)) }}>
        <Img src={staticFile("jre/logo.png")} style={{ width: 144, height: 139, filter: "drop-shadow(0 2px 10px rgba(0,0,0,0.6))" }} />
      </div>
      {/* chamada de abertura (o título que o cliente deu ao vídeo) */}
      <AbsoluteFill style={{ background: "radial-gradient(ellipse 75% 32% at 50% 20%, rgba(0,0,0,0.82) 0%, rgba(0,0,0,0.55) 55%, rgba(0,0,0,0) 100%)", opacity: kickE * (1 - lin(t, 2.0, 2.5)) }} />
      <div style={{ position: "absolute", left: 100, right: 100, top: 250, textAlign: "center", opacity: kickE * (1 - kickO), filter: `blur(${((1 - kickE) * 14 + kickO * 12).toFixed(1)}px)`, transform: `scale(${(1.15 - 0.15 * kickE).toFixed(4)})` }}>
        <div style={{ fontFamily: CAPS, fontWeight: 600, fontSize: 76, lineHeight: 1.12, letterSpacing: "0.08em", whiteSpace: "pre-line", ...gold(t, 0.4), filter: "drop-shadow(0 3px 16px rgba(0,0,0,0.8))" }}>{c.kicker}</div>
        <div style={{ margin: "26px auto 0", width: 380 * k(t, 0.2, 0.7), height: 2, background: `linear-gradient(90deg, transparent, ${GOLD}, transparent)` }} />
      </div>
      <Lettering t={t} frases={c.frases} stop={endAt} hide={(a) => S.some((s, i) => typeof s.src === "string" && s.src.startsWith("m:palavra") && a >= s.at - 0.05 && a < (S[i + 1]?.at ?? endAt))} />
      {t > endAt - 0.3 && <Final t={t} at={endAt} cta={c.cta} />}
    </AbsoluteFill>
  );
};

const frames = (dur: number) => Math.round((LEAD + dur + 0.25 + END) * EMB_FPS);

