    { at: 20.58, src: 18.3, move: "in", tr: "light", rate: 0.9 },
    { at: 24.01, src: "m:tabuleiro", move: "in", tr: "curtain" },
    { at: 25.1, src: 36.0, move: "left", tr: "page", rate: 0.8 },
    { at: 26.34, src: 47.6, move: "in", tr: "light", rate: 0.8 },
