// peão subindo degraus e ganhando a coroa no topo (caminho, jornada, crescer, primeiro passo)
const Escada: React.FC<P> = ({ u, d }) => {
  const steps = 4, SW = 170, SH = 92, x0 = 540 - (steps * SW) / 2, base = 1240;
  const per = Math.max(0.32, Math.min(0.5, (d - 0.6) / steps));
  let pos = 0;
  for (let i = 0; i < steps - 1; i++) pos += io(u, 0.2 + i * per, 0.2 + i * per + per * 0.75);
  const hop = Math.sin((pos % 1) * Math.PI) * 70;
  const px = x0 + SW / 2 + pos * SW, py = base - SH * (pos + 1);
  const crown = io(u, 0.2 + (steps - 1) * per, 0.2 + (steps - 1) * per + 0.45);
  return (
    <Bg>
      <Cam s={1.12 + 0.1 * lin(u, 0, d)} r={2 - 4 * lin(u, 0, d)} ox={px} oy={py - 80}>
        <Glow x={px} y={py - 120} r={360} a={0.18 + 0.28 * crown} />
        {Array.from({ length: steps }, (_, i) => {
          const lit = k(u, 0.2 + (i - 1) * per + per * 0.7, 0.4) * (i <= Math.round(pos) ? 1 : 0.35) + (i === 0 ? 0.5 : 0);
          return <div key={i} style={{ position: "absolute", left: x0 + i * SW, top: base - SH * (i + 1), width: SW - 8, height: SH * (i + 1), background: "#15100A",
            borderTop: `3px solid rgba(232,203,136,${(0.4 + 0.6 * Math.min(1, lit)).toFixed(2)})`, borderLeft: "1px solid rgba(201,162,90,0.3)", boxShadow: `0 -6px ${(28 * Math.min(1, lit)).toFixed(0)}px rgba(255,210,140,0.25)` }} />;
        })}
        <div style={{ position: "absolute", left: px - 85, top: py - 270 - hop, filter: shadow }}>
          <Piece h={270} id="d-p1" kind="pawn" />
          <div style={{ position: "absolute", left: 85 - 55, top: 34 - 240 * (1 - crown), opacity: lin(crown, 0, 0.3) }}><Crown w={110} id="d-c2" /></div>
        </div>
      </Cam>
    </Bg>
  );
};

