// tabuleiro em perspectiva com o peão avançando (estratégia, forma de enxergar o mundo, movimento)
const Tabuleiro: React.FC<P> = ({ u, d }) => {
  const BH = 2.2, BF = 820, HZ = 640;
  const adv = io(u, 0.3, Math.min(d, 2.2));
  const wc = -3.5 + 2.2 * lin(u, 0, d);
  const proj = (X: number, W: number) => { const z = Math.max(0.2, W - wc); return [540 + (BF * X) / z, HZ + (BF * BH) / z]; };
  const sq: React.ReactNode[] = [];
  for (let r = -3; r < 9; r++) for (let c = -4; c <= 3; c++) {
    if (r + 1 - wc < 0.25) continue;
    const W0 = Math.max(r, wc + 0.25), p = [proj(c, W0), proj(c + 1, W0), proj(c + 1, r + 1), proj(c, r + 1)];
    const z = (W0 + r + 1) / 2 - wc, fade = Math.min(1, 2.6 / z);
    sq.push(<polygon key={`${r}_${c}`} points={p.map(([x, y]) => `${x.toFixed(1)},${y.toFixed(1)}`).join(" ")} fill={(r + c) % 2 === 0 ? "#2C2214" : "#0F0B07"} stroke={GOLD} strokeOpacity={0.3 * fade} strokeWidth={1.4} opacity={Math.min(1, 0.2 + fade)} />);
  }
  const wp = 0.5 + 3 * adv, [bx, by] = proj(-0.5 + 1, wp), z = wp - wc, ph = (BF * 1.2) / z;
  const hop = Math.abs(Math.sin(adv * 3 * Math.PI)) * 30;
  return (
    <Bg>
      <Cam s={1.05} r={-3 + 5 * lin(u, 0, d)} oy={900}>
        <Glow x={bx - 40} y={by - ph * 0.5} r={ph * 1.3} a={0.3} />
        <svg width={1080} height={1920} style={{ position: "absolute", inset: 0 }}>{sq}</svg>
        <div style={{ position: "absolute", left: bx - 40 - (ph * 50) / 158, top: by - ph - hop, filter: shadow }}><Piece h={ph} id="d-p2" kind="pawn" /></div>
        <div style={{ position: "absolute", left: proj(-2.5 + 1, 7.5)[0] - 40, top: proj(0, 7.5)[1] - 150, opacity: k(u, 0.2, 0.6), filter: shadow }}><Piece h={150} id="d-k2" kind="king" /></div>
      </Cam>
    </Bg>
  );
};

