};

// joia com raios (essência, exclusivo, algo em que acredita)
const Joia: React.FC<P> = ({ u, d }) => {
  const e = kb(u, 0, 0.7), shine = k(u, 0.5, 0.8);
  return (
    <Bg>
      <Cam s={1.12 - 0.12 * k(u, 0, 0.8) + 0.1 * lin(u, 0.8, d)} r={4 - 8 * lin(u, 0, d)} oy={800}>
        <Glow y={800} r={360 + 220 * shine} a={0.2 + 0.3 * shine} />
        <Rays y={800} r={640} a={0.9 * shine} rot={u * 18} />
        <div style={{ position: "absolute", left: 540 - 200, top: 800 - 200, transform: `scale(${(0.3 + 0.7 * e).toFixed(4)}) rotate(${(-30 * (1 - e) + 4 * Math.sin(u * 2)).toFixed(2)}deg)`, filter: `drop-shadow(0 0 ${(30 + 30 * shine).toFixed(0)}px rgba(255,220,150,0.7))` }}>
          <svg width={400} height={400} viewBox="0 0 100 100" style={{ overflow: "visible" }}>
            <Grad id="d-g1" />
            <path d="M50 8 L90 40 L50 92 L10 40 Z" fill="url(#d-g1)" />
            <path d="M10 40 L90 40 M50 8 L32 40 L50 92 L68 40 Z" fill="none" stroke="#FFF6DD" strokeOpacity={0.55} strokeWidth={1.2} />
          </svg>
        </div>
      </Cam>
    </Bg>
  );
};

// pilares subindo um a um (pilares, quem acredita)
const Pilares: React.FC<P> = ({ u, d }) => {
  const n = 5, gap = 150, x0 = 540 - ((n - 1) * gap) / 2, base = 1220;
  const per = Math.max(0.12, Math.min(0.25, (d - 0.8) / n));
  return (
    <Bg>
      <Cam s={1.12 - 0.08 * lin(u, 0, d)} r={2 - 4 * lin(u, 0, d)} oy={900}>
        <Glow y={900} r={560} a={0.28} />
        {Array.from({ length: n }, (_, i) => {
          const g = kb(u, 0.1 + i * per, 0.5), h = (i === 2 ? 620 : i % 2 ? 540 : 460) * g;
          return (
            <div key={i} style={{ position: "absolute", left: x0 + i * gap - 40, top: base - h, width: 80, height: h, background: "linear-gradient(90deg, #8E6A2F, #F6E2B0 45%, #B08A45)", boxShadow: "0 0 26px rgba(255,210,140,0.35)" }}>
              <div style={{ position: "absolute", left: -14, right: -14, top: -16, height: 18, background: "#E6C47F", borderRadius: 3 }} />
            </div>
          );
        })}
        <div style={{ position: "absolute", left: 540 - 380, width: 760, top: base, height: 22, background: "#C9A25A", borderRadius: 3 }} />
        <div style={{ position: "absolute", left: 540 - 80, top: base - 620 - 170 - 200 * (1 - k(u, 0.15 + n * per, 0.5)), opacity: k(u, 0.15 + n * per, 0.4), filter: shadow }}><Crown w={160} id="d-c4" /></div>
      </Cam>
    </Bg>
  );
};

// fila de peões acendendo um a um (mais pessoas, família de embaixadores, pessoas que acreditam)
const Pessoas: React.FC<P> = ({ u, d }) => {
  const n = 5, gap = 170, x0 = 540 - ((n - 1) * gap) / 2, base = 1180;
  const per = Math.max(0.12, Math.min(0.3, (d - 0.6) / n));
  return (
    <Bg>
      <Cam s={1.15 - 0.12 * lin(u, 0, d)} x={40 - 80 * lin(u, 0, d)} oy={1000}>
        <Glow y={1000} r={600} a={0.22} />
        {Array.from({ length: n }, (_, i) => {
          const c = Math.abs(i - 2), lit = kb(u, 0.1 + c * per, 0.45), h = 300 - c * 34;
          return (
            <div key={i} style={{ position: "absolute", left: x0 + i * gap - (h * 50) / 158, top: base - h - 40 * (1 - lit), opacity: 0.25 + 0.75 * lit, filter: lit > 0.5 ? shadow : "brightness(0.5)" }}>
              <Piece h={h} id={`d-pp${i}`} kind={i === 2 ? "king" : "pawn"} />
            </div>
          );
        })}
        <Line y={base + 4} w={880} a={0.6} />
      </Cam>
    </Bg>
  );
};

// palavra grande em Cinzel, letra a letra (batida tipográfica: MOVIMENTO, SEM EXCEÇÃO…)
const Palavra: React.FC<P & { w: string }> = ({ u, d, w }) => {
  const words = w.split(" ");
  const longest = Math.max(...words.map((x) => x.length));
  const size = Math.min(170, Math.round(860 / (longest * 0.78)));
  let idx = 0;
  return (
    <Bg>
      <Cam s={1.08 - 0.08 * k(u, 0, 0.6) + 0.06 * lin(u, 0.6, d)} r={-2 + 3 * lin(u, 0, d)} oy={800}>
        <Glow y={800} r={560} a={0.3} />
        <Rays y={800} r={640} a={0.5 * k(u, 0.3, 0.6)} rot={u * 10} />
        <div style={{ position: "absolute", left: 60, right: 60, top: 800 - (words.length * size * 1.1) / 2, display: "flex", flexDirection: "column", alignItems: "center" }}>
          {words.map((x, j) => (
            <div key={j} style={{ display: "flex", lineHeight: 1.1 }}>
              {x.split("").map((c) => {
                const a = 0.04 * idx++, e = kb(u, a, 0.5);
                return <span key={idx} style={{ display: "inline-block", fontFamily: CAPS, fontWeight: 600, fontSize: size, letterSpacing: "0.04em", ...goldText(u, idx * 8), opacity: Math.min(1, e * 2), transform: `translateY(${((1 - e) * 120).toFixed(1)}px) scale(${(1.6 - 0.6 * e).toFixed(3)})`, filter: `blur(${((1 - Math.min(1, e)) * 12).toFixed(1)}px) drop-shadow(0 4px 18px rgba(0,0,0,0.6))` }}>{c}</span>;
              })}
            </div>
          ))}
        </div>
        <Line y={800 + (words.length * size * 1.1) / 2 + 30} w={600 * k(u, 0.4, 0.6)} />
      </Cam>
    </Bg>
  );
};

export type Desenho = "coroa" | "casal" | "escada" | "convite" | "lista" | "porta" | "selo" | "tabuleiro" | "livro" | "joia" | "pilares" | "pessoas" | `palavra:${string}`;
export const Cena: React.FC<{ kind: Desenho; u: number; d: number }> = ({ kind, u, d }) => {
  if (kind.startsWith("palavra:")) return <Palavra u={u} d={d} w={kind.slice(8)} />;
  const C = { coroa: Coroa, casal: Casal, escada: Escada, convite: Convite, lista: Lista, porta: Porta, selo: Selo, tabuleiro: Tabuleiro, livro: Livro, joia: Joia, pilares: Pilares, pessoas: Pessoas }[kind as Exclude<Desenho, `palavra:${string}`>];
  return <C u={u} d={d} />;
};
export { CREAM };

